namespace esp {

// ---- EspHost ----------------------------------------------------------------------
void EspHost::status(JsonObject o) {
  double pos = mot_.positionDeg(), enc = NAN;
  bool eok = sens_.encoderDeg(&enc);
  o["pos_deg"] = pos;
  if (eok) { o["encoder_deg"] = enc; o["encoder_err_deg"] = enc - pos; }
  else { o["encoder_deg"] = nullptr; o["encoder_err_deg"] = nullptr; }
  o["encoder_raw"] = sens_.raw();
  As5600::Reading ar = as_.read();                    // AGC + MAGNITUDE (s7: put them up front)
  if (ar.ok) {
    o["encoder_agc"] = ar.agc;
    o["encoder_magnitude"] = ar.magnitude;
    o["encoder_magnet"] = !ar.md ? "none" : ar.ml ? "weak" : ar.mh ? "strong" : "ok";
  }
  o["encoder_map"] = sens_.mapValid();
  o["target_minus_actual_usteps"] = mot_.servoError();
  o["driver_uart"] = mot_.uartOk();
  if (mot_.uartOk()) {                                // TMC2209 DRV_STATUS: why a motor would not turn
    Tmc2209::Status ts = tmc_.status();
    if (ts.ok) {
      JsonObject dv = o["driver"].to<JsonObject>();
      dv["ot"] = ts.ot; dv["otpw"] = ts.otpw; dv["s2g"] = ts.s2g; dv["s2vs"] = ts.s2vs;
      dv["open_load"] = ts.ol; dv["standstill"] = ts.standstill; dv["cs_actual"] = ts.cs_actual;
      dv["mscnt"] = ts.mscnt; dv["microsteps"] = tmc_.microsteps();
    }
  }
  o["guard"] = mot_.lastGuard();
  o["overshoot_deg"] = mot_.overshootDeg();          // BACKLASH_UNITS as degrees

  o["rtc_utc"] = clk_.utc();
  o["rtc_lost_power"] = clk_.lostPower();
  float tc;
  if (rtc_.temperature(&tc)) o["rtc_temp_c"] = tc;

  JsonObject g = o["gps"].to<JsonObject>();
  const Nmea::Fix &f = gps_.nmea();
  g["powered"] = gps_.on();
  g["fix"] = f.rmc_ok && f.quality >= 1;
  g["sats"] = f.sats;
  g["hdop"] = f.hdop;
  if (f.rmc_ok) { g["lat"] = f.lat; g["lon"] = f.lon; }

  o["battery_v"] = sens_.batteryV();

  JsonObject s = o["schedule"].to<JsonObject>();
  scheduleInfo(s);

  JsonObject r = o["radio"].to<JsonObject>();
  r["ssid"] = web::apOn() ? web::ssid() : "";
  r["clients"] = web::clients();

  o["stay_awake"] = System::stayAwake();
  o["uptime_s"] = millis() / 1000;
  o["free_heap"] = ESP.getFreeHeap();
  o["littlefs_free"] = (uint32_t)(LittleFS.totalBytes() - LittleFS.usedBytes());
}

bool EspHost::scheduleText(std::string *out) {
  String s;
  if (!sstore_.text(&s)) return false;
  out->assign(s.c_str(), s.length());
  return true;
}

void EspHost::scheduleInfo(JsonObject o) {
  o["valid"] = sstore_.valid();
  o["source"] = sstore_.source();
  app::NightPlan p = sstore_.schedule().next(clk_.utc());
  if (p.valid) {
    o["next_start_utc"] = p.start_utc;
    o["next_stop_utc"] = p.stop_utc;
    o["next_start_deg"] = p.start_deg;
    o["next_fallback"] = p.fallback;
  } else {
    o["next_start_utc"] = nullptr;
  }
}

bool EspHost::uploadSchedule(const char *json, size_t len, app::Messages *err, app::Messages *warn) {
  return sstore_.upload(json, len, clk_.utc(), err, warn);
}

int EspHost::nights(int n, std::string *nd) {
  String s;
  int got = store_.tail(n, &s);
  nd->assign(s.c_str(), s.length());
  return got;
}

// ---- web -------------------------------------------------------------------------
namespace web {

static WebServer server(80);
static DNSServer dns;
static net::Api *api_ = nullptr;
static bool ap_ = false;
static char ssid_[24] = "";
static const IPAddress AP_IP(192, 168, 4, 1);

static void sendResponse(const net::Response &r) {
  server.sendHeader("Cache-Control", "no-store");
  server.send(r.code, r.type, String(r.body.c_str()));
}

static void handleApi() {
  const char *m = "GET";
  switch (server.method()) {
    case HTTP_POST: m = "POST"; break;
    case HTTP_PUT: m = "PUT"; break;
    case HTTP_DELETE: m = "DELETE"; break;
    default: break;
  }
  // WebServer parses the query into args; put it back together for Api
  String q;
  for (int i = 0; i < server.args(); i++) {
    if (server.argName(i) == "plain") continue;
    if (q.length()) q += '&';
    q += server.argName(i) + "=" + server.arg(i);
  }
  String body = server.hasArg("plain") ? server.arg("plain") : String();
  String path = server.uri();
  net::Request rq;
  rq.method = m; rq.path = path.c_str(); rq.query = q.c_str();
  rq.body = body.c_str(); rq.body_len = body.length();
  sendResponse(api_->handle(rq));
}

static void handleUi() {
  server.sendHeader("Content-Encoding", "gzip");
  server.sendHeader("Cache-Control", "max-age=86400");
  server.send_P(200, "text/html", (const char *)UI_GZ, UI_GZ_LEN);
}

static void handleOther() {
  String u = server.uri();
  if (u.startsWith("/api/")) { handleApi(); return; }
  // captive-portal probes and anything else: send the phone to the UI
  server.sendHeader("Location", "http://192.168.4.1/");
  server.send(302, "text/plain", "");
}

void begin(net::Api &api) {
  api_ = &api;
  uint8_t mac[6];
  WiFi.macAddress(mac);
  snprintf(ssid_, sizeof ssid_, "StarTracker-%02X%02X", mac[4], mac[5]);
  server.on("/", HTTP_GET, handleUi);
  server.on("/index.html", HTTP_GET, handleUi);
  server.onNotFound(handleOther);
  WiFi.mode(WIFI_OFF);
}

void radio(app::Radio r) {
  bool want_ap = r == app::Radio::Ap;
  if (want_ap == ap_) {
    if (r == app::Radio::Sta) Serial.println("radio: STA wanted (GoPro link, slice 6) -- left off");
    return;
  }
  if (want_ap) {
    WiFi.mode(WIFI_AP);
    WiFi.softAPConfig(AP_IP, AP_IP, IPAddress(255, 255, 255, 0));
    bool ok = WiFi.softAP(ssid_, AP_PASS, AP_CHANNEL, 0, 4);
    server.begin();
    dns.setErrorReplyCode(DNSReplyCode::NoError);
    dns.start(53, "*", AP_IP);
    ap_ = true;
    Serial.printf("radio: AP %s '%s' on ch %d, http://192.168.4.1/\n", ok ? "up" : "FAILED", ssid_, AP_CHANNEL);
  } else {
    dns.stop();
    server.stop();
    WiFi.softAPdisconnect(true);
    WiFi.mode(WIFI_OFF);
    ap_ = false;
    Serial.printf("radio: off%s\n", r == app::Radio::Sta ? " (STA is slice 6)" : "");
  }
}

void service() {
  if (!ap_) return;
  dns.processNextRequest();
  server.handleClient();
}

bool apOn() { return ap_; }
const char *ssid() { return ssid_; }
int clients() { return ap_ ? WiFi.softAPgetStationNum() : 0; }

net::Response call(const char *method, const char *pq, const char *body) {
  String s(pq);
  int qi = s.indexOf('?');
  String path = qi >= 0 ? s.substring(0, qi) : s;
  String q = qi >= 0 ? s.substring(qi + 1) : String();
  net::Request rq;
  rq.method = method; rq.path = path.c_str(); rq.query = q.c_str();
  rq.body = body; rq.body_len = strlen(body);
  return api_->handle(rq);
}

}  // namespace web
}  // namespace esp
